    descriptionAdvanced: {
      de: "Das Everest-Basislager in Nepal, auf einer Höhe von 5.364 Metern gelegen, ist der Ausgangspunkt für die meisten Expeditionen zum Gipfel des Mount Everest über die Südostgrat-Route. Es ist ein belebtes, saisonales Zeltlager im Khumbu-Gletscher, das jedes Jahr von Tausenden von Trekkern und Bergsteigern besucht wird. Der Weg dorthin, meist ein 8-tägiger Marsch von Lukla aus, ist eine Herausforderung für sich und führt durch das Herz des Sagarmatha-Nationalparks, einem UNESCO-Weltkulturerbe. Besucher erleben die einzigartige Sherpa-Kultur, passieren Hängebrücken und Klöster. Das Lager selbst bietet eine surreale Landschaft aus Eisformationen und den umliegenden schneebedeckten Gipfeln wie dem Pumori und dem Khumbutse, stellt aber aufgrund der extremen Höhe und der dünnen Luft eine erhebliche physiologische Herausforderung dar.",
      hu: "A nepáli Everest-alaptábor, mely 5364 méteres magasságban fekszik, a Mount Everest délkeleti gerincén induló legtöbb expedíció kiindulópontja. Ez egy nyüzsgő, szezonális sátortábor a Khumbu-gleccseren, amelyet évente több ezer túrázó és hegymászó látogat. Az odavezető út, amely jellemzően egy 8 napos gyalogtúra Luklából, önmagában is kihívást jelent, és a Sagarmatha Nemzeti Park, egy UNESCO Világörökségi helyszín szívén halad keresztül. A látogatók megtapasztalhatják az egyedülálló serpa kultúrát, függőhidakon és kolostorokon kelnek át. Maga a tábor szürreális tájképet nyújt jégképződményekkel és a környező, hóval borított csúcsokkal, mint a Pumori és a Khumbutse, de az extrém magasság és a ritka levegő komoly fiziológiai kihívást jelent.",
      ro: "Tabăra de bază Everest din Nepal, situată la o altitudine de 5.364 de metri, este punctul de plecare pentru majoritatea expedițiilor către vârful Muntelui Everest pe ruta crestei de sud-est. Este o tabără de corturi sezonieră și aglomerată pe ghețarul Khumbu, vizitată de mii de trekkeri și alpiniști în fiecare an. Traseul până acolo, de obicei o drumeție de 8 zile de la Lukla, este o provocare în sine și trece prin inima Parcului Național Sagarmatha, un sit al Patrimoniului Mondial UNESCO. Vizitatorii experimentează cultura unică Sherpa, traversează poduri suspendate și mănăstiri. Tabăra însăși oferă un peisaj suprarealist de formațiuni de gheață și vârfurile înzăpezite din jur, cum ar fi Pumori și Khumbutse, dar reprezintă o provocare fiziologică semnificativă din cauza altitudinii extreme și a aerului rarefiat.",
      en: "The Everest Base Camp in Nepal, located at an altitude of 5,364 meters, is the starting point for most expeditions to the summit of Mount Everest via the southeast ridge route. It is a bustling, seasonal tent city on the Khumbu Glacier, visited by thousands of trekkers and mountaineers each year. The journey there, typically an 8-day trek from Lukla, is a challenge in itself, passing through the heart of Sagarmatha National Park, a UNESCO World Heritage site. Visitors experience the unique Sherpa culture, cross suspension bridges, and pass monasteries. The camp itself offers a surreal landscape of ice formations and the surrounding snow-capped peaks like Pumori and Khumbutse, but poses a significant physiological challenge due to the extreme altitude and thin air.",
      es: "El campamento base del Everest en Nepal, situado a 5.364 metros de altitud, es el punto de partida de la mayoría de las expediciones a la cima del Everest por la ruta de la arista sureste. Es un bullicioso campamento de tiendas estacionales en el glaciar de Khumbu, visitado cada año por miles de senderistas y montañeros. El camino hasta allí, generalmente una marcha de 8 días desde Lukla, es un desafío en sí mismo y atraviesa el corazón del Parque Nacional de Sagarmatha, Patrimonio de la Humanidad de la UNESCO. Los visitantes experimentan la cultura sherpa única, pasan por puentes colgantes y monasterios. El campamento en sí ofrece un paisaje surrealista de formaciones de hielo y picos circundantes cubiertos de nieve como el Pumori y el Khumbutse, pero representa un desafío fisiológico considerable debido a la extrema altitud y al aire enrarecido.",
      pt: "O campo base do Everest no Nepal, localizado a uma altitude de 5.364 metros, é o ponto de partida para a maioria das expedições ao cume do Monte Everest através da rota da aresta sudeste. É um acampamento sazonal movimentado no Glaciar Khumbu, visitado anualmente por milhares de trekkers e alpinistas. O caminho até lá, geralmente uma marcha de 8 dias a partir de Lukla, é um desafio por si só e atravessa o coração do Parque Nacional Sagarmatha, Património Mundial da UNESCO. Os visitantes vivenciam a cultura única dos Sherpas, atravessam pontes suspensas e mosteiros. O próprio campo oferece uma paisagem surreal de formações de gelo e picos circundantes cobertos de neve, como o Pumori e o Khumbutse, mas representa um desafio fisiológico considerável devido à altitude extrema e ao ar rarefeito.",
      fr: "Le camp de base de l'Everest au Népal, situé à une altitude de 5 364 mètres, est le point de départ de la plupart des expéditions vers le sommet du mont Everest via la route de l'arête sud-est. Il s'agit d'un campement de tentes saisonnier et animé sur le glacier du Khumbu, visité chaque année par des milliers de randonneurs et d'alpinistes. Le trajet pour s'y rendre, généralement une marche de 8 jours au départ de Lukla, est un défi en soi et traverse le cœur du parc national de Sagarmatha, classé au patrimoine mondial de l'UNESCO. Les visiteurs y découvrent la culture unique des Sherpas, franchissent des ponts suspendus et visitent des monastères. Le camp lui-même offre un paysage surréaliste de formations de glace et de sommets enneigés environnants tels que le Pumori et le Khumbutse, mais constitue un défi physiologique important en raison de l'altitude extrême et de la raréfaction de l'air.",
    },
