        ro: ["Fondare: 1969 de către Lama Yeshe și Lama Zopa Rinpoche.", "Tradiție: Budism tibetan (tradiția Gelug).", "Locuitori: Peste 360 de călugări, lama, profesori și muncitori.", "Cursuri: Oferă cursuri de una până la zece zile și un curs de meditație de o lună.", "Locație: Dealul Kopan, la nord de Bodnath, Kathmandu.", "Specialitate: Cunoscut ca centru de predare pentru studenții occidentali de Dharma.", "Reconstrucție: Lucrări extinse de reconstrucție au fost efectuate după cutremurul din 2015."],
        en: ["Founded: 1969 by Lama Yeshe and Lama Zopa Rinpoche.", "Tradition: Tibetan Buddhism (Gelug tradition).", "Residents: Over 360 monks, lamas, teachers, and workers.", "Courses: Offers one- to ten-day courses and a one-month meditation course.", "Location: Kopan Hill, north of Bodnath, Kathmandu.", "Specialty: Known as a teaching center for Western Dharma students.", "Reconstruction: Extensive reconstruction work was carried out after the 2015 earthquake."],
        es: ["Fundación: 1969 por Lama Yeshe y Lama Zopa Rinpoche.", "Tradición: Budismo tibetano (tradición Gelug).", "Organización: Parte de la Foundation for the Preservation of the Mahayana Tradition (FPMT).", "Habitantes: Más de 360 monjes, lamas, maestros y trabajadores.", "Cursos: Ofrece cursos de uno a diez días y un curso de meditación de un mes.", "Ubicación: Colina de Kopan, al norte de Bodnath, Katmandú.", "Especialidad: Conocido como centro de enseñanza para estudiantes de Dharma occidentales.", "Reconstrucción: Tras el terremoto de 2015 se realizaron importantes trabajos de reconstrucción."],
        pt: ["Fundação: 1969 pelo Lama Yeshe e Lama Zopa Rinpoche.", "Tradição: Budismo tibetano (tradição Gelug).", "Organização: Parte da Foundation for the Preservation of the Mahayana Tradition (FPMT).", "Habitantes: Mais de 360 monges, lamas, professores e trabalhadores.", "Cursos: Oferece cursos de um a dez dias e um curso de meditação de um mês.", "Localização: Colina de Kopan, a norte de Bodnath, Kathmandu.", "Particularidade: Conhecido como centro de ensino para estudantes ocidentais de Dharma.", "Reconstrução: Após o sismo de 2015, foram realizados extensos trabalhos de reconstrução."],
        fr: ["Fondation : 1969 par Lama Yeshe et Lama Zopa Rinpoché.", "Tradition : Bouddhisme tibétain (tradition Gelug).", "Organisation : Fait partie de la Foundation for the Preservation of the Mahayana Tradition (FPMT).", "Habitants : Plus de 360 moines, lamas, enseignants et travailleurs.", "Cours : Propose des cours de un à dix jours et un cours de méditation d'un mois.", "Localisation : Colline de Kopan, au nord de Bodnath, Katmandou.", "Particularité : Réputé comme centre d'enseignement pour les étudiants occidentaux du Dharma.", "Reconstruction : D'importants travaux de reconstruction ont été menés après le séisme de 2015."],
