        en: ["Significance: One of the most important Shakti Pithas.", "Legend: The place where Sati's knees (or vagina) fell.", "Name: 'Guhyeshwari' means 'Secret Goddess'.", "Location: Near the Pashupatinath Temple, on the banks of the Bagmati.", "Veneration: In the center is a water-filled opening (Yoni), not an idol.", "Year of construction: 17th century by King Pratap Malla.", "Architecture: Pagoda style.", "Access: The inner courtyard is accessible only to Hindus."],
